import { MakeLogicType, actions, kea, listeners, path, reducers } from 'kea'
import posthog from 'posthog-js'

import { MessagesOpening } from './types'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface traceMessagesOpeningLogicValues {
    messagesOpening: MessagesOpening
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface traceMessagesOpeningLogicActions {
    setMessagesOpening: (opening: MessagesOpening) => {
        opening: MessagesOpening
    }
}

export type traceMessagesOpeningLogicType = MakeLogicType<
    traceMessagesOpeningLogicValues,
    traceMessagesOpeningLogicActions
>

export const traceMessagesOpeningLogic = kea<traceMessagesOpeningLogicType>([
    path(['products', 'ai_observability', 'frontend', 'redesign', 'trace', 'traceMessagesOpeningLogic']),
    actions({
        setMessagesOpening: (opening: MessagesOpening) => ({ opening }),
    }),
    reducers({
        messagesOpening: [
            'lastTurn' as MessagesOpening,
            // A rename of this key resets everyone's stored choice.
            { persist: true, storageKey: 'ai_observability.trace_messages_opening' },
            {
                setMessagesOpening: (_, { opening }) => opening,
            },
        ],
    }),
    listeners(() => ({
        setMessagesOpening: ({ opening }) => {
            // A rename of this event or of the `to` property breaks every insight that filters on them.
            posthog.capture('llma trace messages opening switched', { to: opening })
        },
    })),
])
